import{_ as n,o as t,c as r,a2 as a}from"./chunks/framework.Bg-Zxr5O.js";const l=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/Missing-Value-Functions.md","filePath":"manual-zh/Missing-Value-Functions.md","lastUpdated":1785684581000}'),o={name:"manual-zh/Missing-Value-Functions.md"};function s(p,e,i,_,c,m){return t(),r("div",null,[...e[0]||(e[0]=[a('<h4 id="_7-7-4-缺失值函数" tabindex="-1">7.7.4 缺失值函数 <a class="header-anchor" href="#_7-7-4-缺失值函数" aria-label="Permalink to &quot;7.7.4 缺失值函数&quot;">​</a></h4><p>缺失值函数接受各种数值参数并产生各种类型的結果。除非下面另有说明，这些函数内表达式参数的正常求值规则适用。特别是，数值型变量的用户缺失值会被转换为系统缺失值。</p><p>Function: __<strong>MISSING</strong> <em>( expr)</em></p><p>当 expr 只是数值型变量的名称时，如果该变量具有系统缺失值或是用户缺失值，则返回 1。对于任何其他值，返回 0。如果 expr 采用其他形式，则当值为系统缺失值时函数返回 1，否则返回 0。</p><p>Function: __<strong>NMISS</strong> <em>( expr [, expr]…)</em></p><p>每个参数必须是数值表达式。返回列表中系统缺失值的数量，列表可以包含使用 <code>var1 TO var2</code> 语法的变量范围。</p><p>Function: __<strong>NVALID</strong> <em>( expr [, expr]…)</em></p><p>每个参数必须是数值表达式。返回列表中非系统缺失值的数量。列表可以包含使用 <code>var1 TO var2</code> 语法的变量范围。</p><p>Function: __<strong>SYSMIS</strong> <em>( expr)</em></p><p>如果 expr 具有系统缺失值，则返回 1，否则返回 0。</p><p>Function: __<strong>VALUE</strong> <em>( variable)</em> Function: __<strong>VALUE</strong> <em>( vector(index))</em></p><p>阻止变量或向量元素的用户缺失值被转换为系统缺失值，并始终产生其实际值，无论它是有效值、用户缺失值还是系统缺失值。</p>',12)])])}const d=n(o,[["render",s]]);export{l as __pageData,d as default};
